#![allow(dead_code)]
#[path = "codec.rs"] mod hpack;
use std::{hint::black_box, time::Instant};
fn main() {
    let fields: &[(&[u8], &[u8])] = &[(b":status",b"200"),(b":method",b"POST"),(b":status",b"418"),(b"content-type",b"application/json"),(b"content-length",b"1024"),(b"server",b"maximus"),(b"www-authenticate",b"Basic"),(b"x-custom",b"opaque"),(b"accept-encoding",b"gzip, deflate")];
    for (i, &(n,v)) in fields.iter().enumerate() {
        let mut out=Vec::with_capacity(256);
        hpack::encode([(n,v)],&mut out);
        assert_eq!(hpack::Decoder::new(0,4096,10).decode(&out).unwrap(),[(n.to_vec(),v.to_vec())]);
        let wire=out.clone();
        let t=Instant::now();
        for _ in 0..1000000 {out.clear();hpack::encode(black_box([(n,v)]),black_box(&mut out));black_box(&out);}
        println!("case={i} ns={:.3} wire={wire:x?}",t.elapsed().as_nanos() as f64/1000000.0);
    }
}

